import re
from dataclasses import dataclass

_NUMBER = r"(\d+(?:[.,]\d+)?)"
_PATTERNS = {
    "protein": re.compile(r"белки\s+" + _NUMBER),
    "fat": re.compile(r"жиры\s+" + _NUMBER),
    "carbs": re.compile(r"углеводы\s+" + _NUMBER),
    "kcal": re.compile(_NUMBER + r"\s*ккал"),
}
_LABELS = {"protein": "белки", "fat": "жиры", "carbs": "углеводы", "kcal": "ккал"}


@dataclass(frozen=True)
class Kbju:
    protein: float
    fat: float
    carbs: float
    kcal: float


def parse_kbju(value: str) -> Kbju:
    block = value.split("<br>", 1)[0]
    numbers = {}
    for field, pattern in _PATTERNS.items():
        match = pattern.search(block)
        if match is None:
            raise ValueError(f"в строке КБЖУ нет значения «{_LABELS[field]}»: {block!r}")
        numbers[field] = float(match.group(1).replace(",", "."))
    if numbers["kcal"] <= 0:
        raise ValueError(f"ккал в строке КБЖУ должны быть больше нуля: {block!r}")
    return Kbju(**numbers)
from core.kbju import Kbju


def score(kbju: Kbju) -> float:
    if kbju.kcal <= 0:
        raise ValueError("ккал должны быть больше нуля")
    return round(kbju.protein * 4 / kbju.kcal, 3)


def coins_for_answer(correct: bool, streak: int) -> int:
    """streak — длина серии верных ответов подряд, включая текущий."""
    if streak < 0:
        raise ValueError("длина серии не может быть отрицательной")
    if correct and streak < 1:
        raise ValueError("при верном ответе серия должна быть не меньше 1")
    if not correct:
        return 0
    if streak >= 3:
        return 15
    return 10


# Нижняя граница процента -> ранг, от старшего к младшему.
_RANKS = [
    (100, "true adam"),
    (80, "chad"),
    (70, "chadlite"),
    (60, "HTN"),
    (50, "MTN"),
    (40, "LTN"),
    (20, "sub5"),
    (0, "sub3"),
]


def rank(correct_count: int) -> str:
    if not 0 <= correct_count <= 10:
        raise ValueError("число верных ответов должно быть от 0 до 10")
    percent = correct_count / 10 * 100
    for threshold, name in _RANKS:
        if percent >= threshold:
            return name
import json
import unittest
from pathlib import Path

from core.kbju import Kbju, parse_kbju

FIXTURES = Path(__file__).parent / "fixtures"
KBJU_PROPERTY = "Пищевая и энергетическая ценность в 100 г"


def kbju_value(fixture: str, product_id: int) -> str:
    data = json.loads((FIXTURES / fixture).read_text(encoding="utf-8"))
    item = next(i for i in data["data"]["items"] if i["id"] == product_id)
    return next(p["value"] for p in item["properties"] if p["name"] == KBJU_PROPERTY)


class ParseKbjuTest(unittest.TestCase):
    def test_takes_first_manufacturer_block_before_br(self):
        # Творог 5%, 180 г: второй производитель отличается (углеводы 1.8; 116.2 ккал)
        value = kbju_value("search_tvorog.json", 27695)
        self.assertEqual(parse_kbju(value), Kbju(protein=16, fat=5, carbs=3, kcal=121))

    def test_parses_real_fixture_formats(self):
        cases = [
            # хвост «Поставщики:» без <br>
            ("search_tvorog.json", 185, Kbju(protein=16, fat=5, carbs=3, kcal=121)),
            ("search_tvorog.json", 24165, Kbju(protein=16, fat=9, carbs=3, kcal=157)),
            # лишние «соль - 5.5 г» и двойная запятая перед ними
            ("search_chips.json", 81955, Kbju(protein=58.7, fat=4.9, carbs=5.6, kcal=301.3)),
            # «сахара (общие) - 1.5 г, соль - 2.6 г» во втором блоке не мешают первому
            ("search_chips.json", 65291, Kbju(protein=5.5, fat=30, carbs=53, kcal=504)),
        ]
        for fixture, product_id, want in cases:
            with self.subTest(product_id=product_id):
                self.assertEqual(parse_kbju(kbju_value(fixture, product_id)), want)

    def test_accepts_comma_as_decimal_separator(self):
        value = "белки 5,5 г, жиры 38 г, углеводы 53,2 г; 576,4 ккал"
        self.assertEqual(parse_kbju(value), Kbju(protein=5.5, fat=38, carbs=53.2, kcal=576.4))

    def test_missing_number_raises_value_error(self):
        cases = {
            "белки": "жиры 5 г, углеводы 3 г; 121 ккал",
            "жиры": "белки 16 г, углеводы 3 г; 121 ккал",
            "углеводы": "белки 16 г, жиры 5 г; 121 ккал",
            "ккал": "белки 16 г, жиры 5 г, углеводы 3 г",
        }
        for missing, value in cases.items():
            with self.subTest(missing=missing):
                with self.assertRaises(ValueError):
                    parse_kbju(value)

    def test_does_not_borrow_numbers_from_next_block(self):
        value = 'ООО "А": белки 16 г, жиры 5 г; 121 ккал<br>ООО "Б": белки 16 г, жиры 5 г, углеводы 3 г; 121 ккал'
        with self.assertRaises(ValueError):
            parse_kbju(value)

    def test_zero_kcal_raises_value_error(self):
        with self.assertRaises(ValueError):
            parse_kbju("белки 0 г, жиры 0 г, углеводы 0 г; 0 ккал")


if __name__ == "__main__":
    unittest.main()
import unittest

from core.kbju import Kbju
from core.scoring import coins_for_answer, rank, score


class ScoreTest(unittest.TestCase):
    def test_protein_share_of_kcal_rounded_to_three_places(self):
        cases = [
            (Kbju(protein=16, fat=5, carbs=3, kcal=121), 0.529),  # 64 / 121 = 0.52892
            (Kbju(protein=58.7, fat=4.9, carbs=5.6, kcal=301.3), 0.779),  # 234.8 / 301.3 = 0.77929
            (Kbju(protein=5.5, fat=30, carbs=53, kcal=504), 0.044),  # 22 / 504 = 0.04365
        ]
        for kbju, want in cases:
            with self.subTest(kbju=kbju):
                self.assertEqual(score(kbju), want)

    def test_non_positive_kcal_raises_value_error(self):
        for kcal in (0, -5):
            with self.subTest(kcal=kcal):
                with self.assertRaises(ValueError):
                    score(Kbju(protein=10, fat=1, carbs=1, kcal=kcal))


class CoinsForAnswerTest(unittest.TestCase):
    def test_reward_depends_on_correctness_and_streak(self):
        # streak — длина серии верных ответов подряд, включая текущий
        cases = [
            (False, 0, 0),
            (True, 1, 10),
            (True, 2, 10),
            (True, 3, 15),
            (True, 4, 15),
            (True, 10, 15),
        ]
        for correct, streak, want in cases:
            with self.subTest(correct=correct, streak=streak):
                self.assertEqual(coins_for_answer(correct, streak), want)

    def test_inconsistent_streak_raises_value_error(self):
        for correct, streak in [(True, 0), (False, -1), (True, -1)]:
            with self.subTest(correct=correct, streak=streak):
                with self.assertRaises(ValueError):
                    coins_for_answer(correct, streak)


class RankTest(unittest.TestCase):
    def test_rank_for_every_possible_result(self):
        # процент = верные / 10 × 100
        cases = [
            (0, "sub3"),
            (1, "sub3"),
            (2, "sub5"),
            (3, "sub5"),
            (4, "LTN"),
            (5, "MTN"),
            (6, "HTN"),
            (7, "chadlite"),
            (8, "chad"),
            (9, "chad"),
            (10, "true adam"),
        ]
        for correct_count, want in cases:
            with self.subTest(correct_count=correct_count):
                self.assertEqual(rank(correct_count), want)

    def test_count_outside_zero_to_ten_raises_value_error(self):
        for correct_count in (-1, 11):
            with self.subTest(correct_count=correct_count):
                with self.assertRaises(ValueError):
                    rank(correct_count)


if __name__ == "__main__":
    unittest.main()
